// tb.v: random-stimulus testbench for Checked, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg push_valid = 1'b0;
    reg [7:0] push_data = 8'd0;
    reg pop_ready = 1'b0;
    wire push_ready;
    wire [2:0] level;
    reg [9:0] stim [0:239];
    integer i;

    Checked dut (
        .clk(clk),
        .rst(rst),
        .push_valid(push_valid),
        .push_data(push_data),
        .push_ready(push_ready),
        .pop_ready(pop_ready),
        .level(level)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {push_valid, push_data, pop_ready} = stim[i];
            #1;
            $display("D %0d %h %h", i, push_ready, level);
            cycle_clk;
        end
        $finish;
    end
endmodule
